"""The chain of generated files: tools/stages.yaml declares, for each stage, what it reads, what it writes and the
skill that regenerates it; dvc.yaml is generated from it, DVC records each stage in dvc.lock, and the check reports
every stage whose inputs or outputs moved since.

Three commands: `ensure-up-to-date` (check_main), `mark-up-to-date` (mark_main), `recorded-at` (recorded_at_main)."""
from __future__ import annotations

import json
import logging
import os
import posixpath
import re
import shutil
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

import yaml

from .folder import Corpus, Folder, glob_to_regex
from .links import check_folder
from .pins import GitHistory

STAGES_PATH = 'tools/stages.yaml'
HEADER = f'# Generated by `just ensure-up-to-date` from {STAGES_PATH}. Do not edit.'
INSTALL = 'uv sync --project tools'
RUN = 'run /ensure-up-to-date'
SHOWN_ITEMS, SHOWN_LINES = 20, 5


class FormatError(ValueError):
    """stages.yaml, or a file it expands over, breaks a rule; the message is the one line to show."""

    @property
    def message(self) -> str:
        return str(self.args[0])


@dataclass
class StageDecl:
    name: str
    skill: str
    inputs: list[str]
    outputs: list[str]
    each: str | None = None  # one-to-one: the glob whose files are the items
    root: str | None = None  # one-to-one: an item's id is its path relative to root, without its extension
    exclude: list[str] = field(default_factory=list)


@dataclass
class Declaration:
    dvc: str
    stages: list[StageDecl]


def parse_declaration(text: str) -> Declaration:
    try:
        y = yaml.safe_load(text)
    except yaml.YAMLError as e:
        mark = getattr(e, 'problem_mark', None)
        where = f' (line {mark.line + 1})' if mark is not None else ''
        raise FormatError(f'not YAML: {getattr(e, "problem", None) or e}{where}') from None
    if not isinstance(y, dict) or not isinstance(y.get('dvc'), str) or not isinstance(y.get('stages'), dict):
        raise FormatError('stages.yaml needs "dvc: <version>" and a "stages:" map')

    def as_list(stage, m, k) -> list[str]:
        v = m.get(k)
        if v is None:
            return []
        if not isinstance(v, list):
            raise FormatError(f'stage {stage}: {k} must be a list')
        return [str(x) for x in v]

    def as_str(stage, m, k) -> str | None:
        v = m.get(k)
        if v is None or isinstance(v, str):
            return v
        raise FormatError(f'stage {stage}: {k} must be a string')

    stages = []
    for key, m in y['stages'].items():
        n = str(key)
        if not isinstance(m, dict):
            raise FormatError(f'stage {n} needs a map (skill, inputs, outputs)')
        s = StageDecl(n, str(m.get('skill')), as_list(n, m, 'inputs'), as_list(n, m, 'outputs'),
                      as_str(n, m, 'each'), as_str(n, m, 'root'), as_list(n, m, 'exclude'))
        if not s.inputs or m.get('skill') is None:
            raise FormatError(f'stage {n} needs a skill and inputs')
        if s.each is not None and s.root is None:
            raise FormatError(f'one-to-one stage {n} needs a root')
        if '--' in n:
            raise FormatError(f'stage name {n} contains --')
        stages.append(s)
    return Declaration(y['dvc'], stages)


def declaration_at(root: Path) -> Declaration:
    return parse_declaration((Path(root) / STAGES_PATH).read_text(encoding='utf-8'))


def declaration_problem(root: Path) -> str | None:
    """Null when root has a stages.yaml that parses; otherwise the one line that says what is wrong."""
    if not (Path(root) / STAGES_PATH).is_file():
        return f'no {STAGES_PATH} at {root}'
    try:
        declaration_at(root)
    except FormatError as e:
        return f'{STAGES_PATH} at {root}: {e.message}'
    return None


# --- expansion ------------------------------------------------------------------------------------------------------

@dataclass
class DvcStage:
    name: str
    decl: str  # the stages.yaml stage it comes from
    cmd: str
    deps: list[str]
    outs: list[str]


def git_files(root: Path) -> list[str]:
    """What git tracks or would track at root and exists on disk: sorted repo-relative posix paths."""
    r = subprocess.run(['git', '-C', str(root), 'ls-files', '--cached', '--others', '--exclude-standard', '-z'],
                       capture_output=True, text=True, encoding='utf-8')
    if r.returncode != 0:
        raise RuntimeError(f'git ls-files in {root}: {r.stderr.strip()}')
    return sorted(f for f in r.stdout.split('\0') if f and (Path(root) / f).exists())


def stage_decl_of(name: str) -> str:
    """The stages.yaml stage a DVC stage name belongs to: the part before the first `--`."""
    return name.split('--', 1)[0]


def _expand(files: list[str], globs, exclude, keep_literal=False) -> list[str]:
    out: set[str] = set()
    for g in globs:
        rx = glob_to_regex(g)
        m = [f for f in files if rx.match(f)]
        if not m and keep_literal and '*' not in g:
            out.add(g)  # an output not built yet: declared, so DVC reports it missing
        out.update(m)
    return sorted(out - set(exclude))


def _fill(pattern: str, each: str, id_: str) -> str:
    group, dot, name = id_.partition('.')
    return (pattern.replace('{each}', each).replace('{id}', id_)
            .replace('{group}', group).replace('{name}', name if dot else id_))


def expand_all(decl: Declaration, files: list[str]) -> list[DvcStage]:
    """Every DVC stage of decl over files, in declaration order: an all-to-all stage as one, a one-to-one stage as
    one per item, named `<stage>--<id>`."""
    files = sorted(files)
    out = []
    for s in decl.stages:
        if s.each is None:
            out.append(DvcStage(s.name, s.name, s.skill, _expand(files, s.inputs, s.exclude),
                                _expand(files, s.outputs, s.exclude)))
            continue
        for item in _expand(files, [s.each], s.exclude):
            rel = posixpath.relpath(item, s.root)
            id_ = rel[:len(rel) - len(posixpath.splitext(rel)[1])]
            if '--' in id_:
                raise FormatError(f'item id "{id_}" of stage {s.name} contains --')
            out.append(DvcStage(f'{s.name}--{id_}', s.name, s.skill,
                                _expand(files, [_fill(g, item, id_) for g in s.inputs], s.exclude, True),
                                _expand(files, [_fill(g, item, id_) for g in s.outputs], s.exclude, True)))
    return out


def _q(s: str) -> str:
    return "'" + s.replace("'", "''") + "'"


def render_dvc_yaml(stages: list[DvcStage]) -> str:
    """dvc.yaml for stages: sorted by name, every scalar quoted, every output `cache: false`; byte-stable."""
    if not stages:
        return HEADER + '\nstages: {}\n'
    lines = [HEADER, 'stages:']
    for s in sorted(stages, key=lambda s: s.name):
        lines += [f'  {_q(s.name)}:', f'    cmd: {_q(s.cmd)}', '    deps:']
        lines += [f'    - {_q(d)}' for d in s.deps]
        if s.outs:
            lines.append('    outs:')
            for o in s.outs:
                lines += [f'    - {_q(o)}:', '        cache: false']
    return '\n'.join(lines) + '\n'


def generated_for(root: Path, decl: Declaration | None = None) -> str:
    return render_dvc_yaml(expand_all(decl or declaration_at(root), git_files(root)))


# --- DVC ------------------------------------------------------------------------------------------------------------

_versions: dict[str, str | None] = {}


def _dvc_version() -> str | None:
    """`dvc --version` of the dvc on PATH, asked once per executable; None when there is none."""
    exe = shutil.which('dvc')
    if exe is None:
        return None
    if exe not in _versions:
        try:
            r = subprocess.run([exe, '--version'], capture_output=True, text=True, encoding='utf-8')
            _versions[exe] = r.stdout.strip() if r.returncode == 0 else f'{r.stdout}{r.stderr}'.strip()
        except OSError:
            _versions[exe] = None
    return _versions[exe]


def dvc_problem(wanted: str) -> str | None:
    """None when the installed DVC is wanted; otherwise what is wrong and how to install it."""
    have = _dvc_version()
    if have is None:
        return f'DVC is not installed. Install it: {INSTALL}'
    if have != wanted:
        return f'DVC {wanted} is required, found "{have}". Install it: {INSTALL}'
    return None


def dvc_status(root: Path) -> dict[str, list[str]]:
    """Every stale stage at root, by name, with one sorted line per moved path: `dep <path> <state>`,
    `out <path> <state>`. Empty when everything is current. Raises RuntimeError when DVC fails."""
    r = subprocess.run(['dvc', 'status', '--json'], cwd=root, capture_output=True, text=True, encoding='utf-8')
    if r.returncode != 0:
        raise RuntimeError((r.stderr.strip() or r.stdout.strip()) or f'exit {r.returncode}')
    data = json.loads(r.stdout.strip() or '{}')
    out = {}
    for name in sorted(data):
        lines = []
        for part in data[name]:
            if not isinstance(part, dict):
                lines.append(str(part))
                continue
            for kind, paths in part.items():
                tag = {'changed deps': 'dep', 'changed outs': 'out'}.get(kind, kind)
                lines += [f'{tag} {p} {state}' for p, state in paths.items()]
        out[name] = sorted(lines)
    return out


def dvc_commit(root: Path, names: list[str]) -> None:
    """Record the stages as current, as their inputs and outputs are now, without running anything: what `dvc commit
    -f <stages>` records, in one pass through DVC's API. Writes only dvc.lock. Raises DvcException; DVC's own log
    (its progress lines, on the streams it bound at import) is silenced, its failures arrive as the exception."""
    from dvc.exceptions import DvcException
    from dvc.logger import set_loggers_level
    from dvc.repo import Repo

    wanted = set(names)
    with set_loggers_level(logging.CRITICAL + 1), Repo(str(root)) as repo, repo.lock:
        stages = [s for s in repo.index.stages if s.name in wanted]
        missing = wanted - {s.name for s in stages}
        if missing:
            raise DvcException('no stage named ' + ', '.join(sorted(missing)))
        for stage in stages:
            stage.save(run_cache=False)  # the run cache only serves `dvc repro`, which never runs here
        stages[0].dvcfile.dump_stages(stages, update_pipeline=False)


# --- the check ------------------------------------------------------------------------------------------------------

def normal_target(target: str) -> str:
    t = target.replace('\\', '/')
    while t.startswith('./'):
        t = t[2:]
    return t.rstrip('/')


def is_under(path: str, target: str) -> bool:
    return not target or path == target or path.startswith(target + '/')


def static_dir(glob: str) -> str:
    """The folder a declared output glob writes into: its part before the first wildcard, cut back to the last `/`."""
    m = re.search(r'[*?\[{]', glob)
    if m is None:
        return glob
    return glob[:m.start()].rpartition('/')[0]


def link_problems_in(root: Path, target: str) -> list:
    """The link problems of the docs folder (corpus.yaml's root) whose repo-relative file lies under target."""
    if not (Path(root) / 'tools' / 'corpus.yaml').is_file():
        return []
    corpus = Corpus.load(root)
    docs = Path(root) / corpus.root
    if not docs.is_dir():
        return []
    found = check_folder(Folder.git(docs), corpus, GitHistory.of(docs), corpus.root.rstrip('/'))
    return sorted(p for p in found if is_under(p.file, target))


def check(root: Path, full=False, target=None, warnings_as_errors=False) -> tuple[str, bool]:
    """Is every stage at root current? The report and whether it is OK. Each stale stage is named with what moved
    and its skill: 20 items of a stage and 5 lines of each, or with full all. With target (repo-relative), only the
    stages with an output under it count, and the links of the docs folder under it are checked too."""
    root = Path(root)
    problem = declaration_problem(root)
    if problem is not None:
        old = '' if (root / STAGES_PATH).is_file() else \
            'this commit predates the freshness check; merge main into it, or push with --no-verify\n'
        return f'{problem}\n{old}{RUN}\n', False
    decl = declaration_at(root)
    problem = dvc_problem(decl.dvc)
    if problem is not None:
        return problem + '\n', False
    out: list[str] = []
    try:
        files = git_files(root)
        expanded = expand_all(decl, files)
    except (FormatError, RuntimeError) as e:
        return f'{e}\n{RUN}\n', False
    dvc_yaml = root / 'dvc.yaml'
    if not dvc_yaml.is_file() or dvc_yaml.read_text(encoding='utf-8') != render_dvc_yaml(expanded):
        out.append('dvc.yaml is out of step with stages.yaml and the files (a file was added, removed or moved).')
    try:
        status = dvc_status(root)
    except (RuntimeError, ValueError) as e:
        out += [f'dvc status failed: {e}', RUN]
        return '\n'.join(out) + '\n', False
    skills = {s.name: s.skill for s in decl.stages}
    t = None if target is None else normal_target(target)
    if t is not None:
        by_name = {s.name: s for s in expanded}
        decls = {s.name: s for s in decl.stages}

        def in_target(name):
            s = by_name.get(name)
            if s is not None and any(is_under(o, t) for o in s.outs):
                return True
            d = decls.get(stage_decl_of(name))
            return d is not None and any(is_under(static_dir(g), t) for g in d.outputs)

        status = {k: v for k, v in status.items() if in_target(k)}
    groups: dict[str, list[str]] = {}
    for name in status:
        groups.setdefault(stage_decl_of(name), []).append(name)
    for d in sorted(groups):
        names = groups[d]
        out.append(f'{d}: {len(names)} stale ({skills.get(d, "unknown skill")})')
        for n in names if full else names[:SHOWN_ITEMS]:
            out.append(f'  {n}')
            out += [f'    {line}' for line in (status[n] if full else status[n][:SHOWN_LINES])]
        if not full and len(names) > SHOWN_ITEMS:
            out.append(f'  … and {len(names) - SHOWN_ITEMS} more')
    stale = bool(out)
    links_fail = False
    if t is not None:
        found = link_problems_in(root, t)
        problems = sum(1 for p in found if not p.warning)
        warnings = len(found) - problems
        links_fail = problems > 0 or (warnings_as_errors and warnings > 0)
        out += [str(p) for p in found]
        if found:
            note = ' (warnings do not fail without --warnings-as-errors)' if warnings and not warnings_as_errors else ''
            out.append(f'links in {t}: {problems} problems, {warnings} warnings{note}')
        if links_fail:
            out.append(f'fix the links in {t} (just links-check, /reconcile-links)')
    if not stale and not links_fail:
        return '\n'.join(out + ['OK']) + '\n', True
    if stale:
        out.append(RUN)
    return '\n'.join(out) + '\n', False


# --- mark and recorded-at -------------------------------------------------------------------------------------------

def mark(root: Path, names: list[str]) -> int:
    """Rewrite dvc.yaml, then record the named stages (a stages.yaml name marks all its items) as current. Prints
    what it did; returns the exit code."""
    root = Path(root)
    problem = declaration_problem(root)
    if problem is None:
        decl = declaration_at(root)
        problem = dvc_problem(decl.dvc)
    if problem is not None:
        print(problem, file=sys.stderr)
        return 1
    if not names:
        print('usage: mark <stage>… | --generate-only', file=sys.stderr)
        return 2
    try:
        stages = expand_all(decl, git_files(root))
    except (FormatError, RuntimeError) as e:
        print(e, file=sys.stderr)
        return 1
    (root / 'dvc.yaml').write_text(render_dvc_yaml(stages), encoding='utf-8')
    if names == ['--generate-only']:
        print(f'dvc.yaml generated: {len(stages)} stage(s), none marked')
        return 0
    wanted = list(dict.fromkeys(s.name for a in names for s in stages if a in (s.name, s.decl)))
    if not wanted:
        print('no stage named ' + ', '.join(names), file=sys.stderr)
        return 1
    try:
        dvc_commit(root, wanted)
    except Exception as e:  # DVC's own errors, and whatever else it raises: one message, no trace
        cause = f': {e.__cause__}' if e.__cause__ else ''
        print(f'dvc commit {" ".join(wanted)} failed:\n{e}{cause}', file=sys.stderr)
        return 1
    print(f'marked up to date: {len(wanted)} stage(s)')
    return 0


def _git(root: Path, *args) -> subprocess.CompletedProcess:
    return subprocess.run(['git', '-C', str(root), *args], capture_output=True, text=True, encoding='utf-8')


def recorded_at(root: Path, stage: str) -> str | None:
    """The commit that last recorded stage: the newest commit whose dvc.lock entry for it equals HEAD's and differs
    from every parent's (a root commit wins), so a merge that only carries a side branch's recording is not the
    commit that recorded it. None when HEAD's dvc.lock has no entry for stage."""
    cache: dict[str, str | None] = {}

    def entry(commit):
        if commit not in cache:
            r = _git(root, 'show', f'{commit}:dvc.lock')
            y = yaml.safe_load(r.stdout) if r.returncode == 0 else None
            e = y.get('stages', {}).get(stage) if isinstance(y, dict) and isinstance(y.get('stages'), dict) else None
            cache[commit] = None if e is None else json.dumps(e)
        return cache[commit]

    head = entry('HEAD')
    if head is None:
        return None
    for c in _git(root, 'log', '--full-history', '--format=%H', '--', 'dvc.lock').stdout.split():
        if entry(c) != head:
            continue
        parents = _git(root, 'rev-list', '--parents', '-n1', c).stdout.split()[1:]
        if all(entry(p) != head for p in parents):
            return c
    return None


# --- the command lines ----------------------------------------------------------------------------------------------

def _toplevel() -> Path:
    r = subprocess.run(['git', 'rev-parse', '--show-toplevel'], capture_output=True, text=True, encoding='utf-8')
    return Path(r.stdout.strip())


class _Usage(Exception):
    pass


def _value(args: list[str], flag: str) -> str | None:
    if flag not in args:
        return None
    i = args.index(flag)
    if i + 1 >= len(args) or args[i + 1].startswith('--'):
        raise _Usage(f'{flag} needs a value')
    return args[i + 1]


def check_main(argv=None) -> int:
    """ensure-up-to-date [--root <dir>] [--full] [--target <path>] [--warnings-as-errors]: exit 0 and OK, or the
    report and exit 1; 2 for a value flag without its value."""
    args = sys.argv[1:] if argv is None else list(argv)
    try:
        root_arg, target = _value(args, '--root'), _value(args, '--target')
    except _Usage as e:
        print(e, file=sys.stderr)
        return 2
    root = Path(os.path.abspath(root_arg)) if root_arg is not None else _toplevel()
    report, ok = check(root, full='--full' in args, target=target, warnings_as_errors='--warnings-as-errors' in args)
    sys.stdout.write(report)
    return 0 if ok else 1


def mark_main(argv=None) -> int:
    """mark-up-to-date <stage>… | --generate-only"""
    return mark(_toplevel(), sys.argv[1:] if argv is None else list(argv))


def recorded_at_main(argv=None) -> int:
    """recorded-at <stage>: the sha that last recorded it, or nothing and exit 1."""
    args = sys.argv[1:] if argv is None else list(argv)
    c = recorded_at(_toplevel(), args[0]) if len(args) == 1 else None
    if c is None:
        return 1
    print(c)
    return 0
